function enterInterior(id,door){leisure?.close();if((driving&&!interiors[id]?.drivable)||dead||(id==='bank'&&bankTarget.hp<=0))return;interior=id;const r=interiors[id];outdoorVisibility.clear();for(let o of scene.children){if(o===hero.g)continue;outdoorVisibility.set(o,o.visible);if(!o.isLight)o.visible=false;}r.g.visible=true;hero.g.visible=true;hero.g.position.set(...r.spawn);if(door&&(door!==r.exits[0]||door.arrival)){const at=door.arrival||[door.at[0],door.at[1]+2];let p=r.safePoint?.(...at)||at;hero.g.position.set(p[0],(r.heightAt?.(...p)||0)+.2,p[1]);}if(driving){ride.parkedInterior=id;ride.g.position.copy(hero.g.position).setY(groundHeight(hero.g.position.x,hero.g.position.z)+.5);ride.g.visible=true;ride.g.rotation.y=Math.PI;hero.g.visible=false;driveSpeed=0;}const heading=door?.arrivalHeading??Math.PI;hero.g.rotation.set(0,heading,0);yaw=door?.arrivalHeading==null?0:heading+Math.PI;pitch=.12;camInit=false;keys.clear();touchControls?.reset();joy.x=joy.y=0;player.kx=player.kz=0;jumping=false;vY=0;fallPeak=null;marker.visible=false;$('#targetInfo').classList.add('hidden');actorLayers?.sync();if(regions?.id===CITY)setWorldLight(regions.night);toast(r.name+' · 门口按 E 出门');}
function leaveInterior(door){if(!interior)return;leisure?.close();if(door?.to){if(chapter.fourth&&!chapter.fourth.canEnter(door.to)){toast('这条通道还没打通 · 先跟进当前线索');return;}if(chapter.third&&!chapter.third.canEnter(door.to,door)){toast('通道还没打通 · 先完成当前目标');return;}const target=interiors[door.to];if(!target){toast('这个通道暂未开放');return;}if(driving&&!target.drivable){toast('先下车，再进入商场');return;}const arrival=target.exits.find(e=>e.to===interior&&(!door.linkId||e.linkId===door.linkId));leaveInterior();enterInterior(door.to,arrival);return;}let id=interior;interior=null;for(let [o,visible]of outdoorVisibility)o.visible=visible;interiors[id].g.visible=false;let p=(door||interiors[id].exits[0]).out;hero.g.position.set(p[0],groundHeight(...p)+.2,p[1]);hero.g.visible=!driving;if(driving){ride.parkedInterior=null;ride.g.position.set(p[0],groundHeight(...p)+.5,p[1]);ride.g.visible=true;hero.g.visible=false;driveSpeed=0;}hero.g.rotation.set(0,Math.PI,0);camInit=false;yaw=0;pitch=.34;keys.clear();touchControls?.reset();joy.x=joy.y=0;player.kx=player.kz=0;jumping=false;vY=0;fallPeak=null;choosePlace(selectedPlace);actorLayers?.sync();if(regions?.id===CITY)setWorldLight(regions.night);toast('回到 '+(regions?.current?.name||'北辰街头'));}
function mapPosition(){if(!interior)return currentPos();let p=interiors[interior].entry;return{x:p[0],z:p[1]};}
function currentPos(){return driving?ride.g.position:hero.g.position;}
function distanceTo(x,z){let p=currentPos();return Math.hypot(p.x-x,p.z-z);}
let impactShake=0;const impactAudio=createImpactAudio(()=>audioCtx,()=>soundOn);
function tone(freq=440,duration=.15,type='sine',vol=.045){if(!soundOn||!audioCtx)return;let osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(vol,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration);}
function say(text,seconds=6){$('#subtitle').classList.remove('hidden');$('#subtitle p').textContent=text;subtitleTimer=seconds;if(!chapter?.dialogue.busy&&soundOn&&'speechSynthesis' in window){speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=1.17;u.pitch=.82;speechSynthesis.speak(u);}}
