function clearOutdoor(x,z,r=2.5){if(regions?.current)return onLand(x,z)&&![...nearbyStatics(x,z,r)].some(b=>contact({x,z,r},staticShape(b))); if(x< -225||x>420||z< -445||z>455||!city.inside(x,z))return false;for(let b of city.buildingShapes){if(b.id==='466202929'&&bankTarget.hp<=0)continue;if(city.inside(x,z,b.points))return false;}let seen=new Set();for(let a=Math.floor((x-r)/32);a<=Math.floor((x+r)/32);a++)for(let b=Math.floor((z-r)/32);b<=Math.floor((z+r)/32);b++)for(let c of staticGrid.get(a+','+b)||[])seen.add(c);return ![...seen].some(b=>!b.disabled&&contact({x,z,r},staticShape(b)));}
function safePoint(x,z,r=.8){if(clearOutdoor(x,z,r))return[x,z];for(let d=2;d<=36;d+=2)for(let i=0;i<16;i++){let a=x+Math.cos(i*Math.PI/8)*d,b=z+Math.sin(i*Math.PI/8)*d;if(clearOutdoor(a,b,r))return[a,b];}return regions?.current?.safe||[18,8];}
