 let movedVehicle=false;
 if(room.drivable&&ride.parkedInterior===interior&&ride.hp>0&&!room.clear(ride.g.position.x,ride.g.position.z,2.6)){
  const point=room.safePoint(ride.g.position.x,ride.g.position.z,2.65);ride.g.position.x=point[0];ride.g.position.z=point[1];ride.vx=ride.vz=ride.kx=ride.kz=0;movedVehicle=true;
 }
